async function api(path, opts = {}) {
  const headers = { 'Content-Type': 'application/json', ...(opts.headers || {}) };
  if (TOKEN) headers['Authorization'] = 'Bearer ' + TOKEN;
  async function tentar() {
    const res = await fetch(path, { ...opts, headers, body: opts.body ? JSON.stringify(opts.body) : undefined });
    let corpoInvalido = false;
    const data = await res.json().catch(() => { corpoInvalido = true; return {}; });
    if (!res.ok) {
      const erro = new Error(data.erro || 'Erro na requisição');
      erro.status = res.status;
      erro.corpo = data;
      // resposta sem JSON válido (ou sem campo erro) não veio do nosso backend — é sintoma de
      // instabilidade da hospedagem (ex: "acordando" após período inativo no plano gratuito),
      // não um erro de validação de verdade
      erro.falhaTransitoria = corpoInvalido || !data.erro || [502, 503, 504].includes(res.status);
      // empresa suspensa (Etapa 7/passo 1): acontece em qualquer chamada, inclusive as silenciosas
      // em segundo plano (sino, chat), que nunca mostram erro pro usuário — por isso o logout e o
      // aviso saem daqui, central, em vez de depender do catch de cada tela.
      // trial expirado (SaaS, passo 2) — mesmo tratamento central da empresa suspensa: pega
      // inclusive quem já estava logado quando o prazo venceu, mesmo numa chamada silenciosa.
      if ((data.codigo === 'empresa_suspensa' || data.codigo === 'teste_expirado') && TOKEN) {
        sair();
        const erroEl = document.getElementById('login-erro');
        if (erroEl) { erroEl.textContent = erro.message; erroEl.classList.remove('hidden'); }
      }
      throw erro;
    }
    return data;
  }
  try {
    return await tentar();
  } catch (e) {
    // instabilidade passageira da hospedagem: tenta mais uma vez sozinho antes de mostrar erro
    // pro usuário — evita ter que clicar de novo em qualquer botão da tela por causa disso
    if (!e.falhaTransitoria) throw e;
    await new Promise((r) => setTimeout(r, 2500));
    return await tentar();
  }
}

// dados de marca da empresa — usados nos PDFs/Word e telas de contato. Antes do login não dá pra
// saber de qual empresa é a sessão (login é só e-mail+senha), então carregarEmpresa() busca uma
// marca genérica só pra tela de login não ficar em branco; assim que USER loga, entrarNoApp()
// troca window._empresa pelos dados reais da empresa do usuário (USER.empresa, vindo do
// login/GET /api/me) — sem isso, PDF gerado por empresa B sairia com o nome da empresa A.
// Os valores de fallback abaixo só entram em jogo se nem uma coisa nem outra estiver disponível.
window._empresa = null;
async function carregarEmpresa() {
  try { window._empresa = (await api('/api/empresa')).empresa; } catch (e) {}
  aplicarMarcaNaTela();
}
// pedido do usuário: "o logo P é da Promarking precisa ser o logo N. Nos relatórios não mexer
// em nada continuar como está logo da Promarking" — login e cabeçalho (a cara da própria Nexor
// Connect, a plataforma) sempre usam a logo padrão do sistema (/logo.png, já fixa no HTML),
// independente da logo própria que a empresa configurou em Minha Empresa. Essa logo própria
// (window._empresa.logo_url) continua valendo só pros PDFs/relatórios (ver carregarLogoDataUri/
// carregarLogoVariantes), que é o que esse campo deve controlar. Ainda assim invalida o cache
// da logo usada nos PDFs sempre que a marca muda, pra um PDF gerado depois de trocar a logo em
// Minha Empresa já sair com a nova.
function aplicarMarcaNaTela() {
  _logoDataUriPromise = null;
  _logoVariantesPromise = null;
}
// pedido do usuário: "na última página aparece o contato da Promarking isso não deve acontecer"
// — os contatos reais da PRO Marking só podem aparecer pra ela mesma (empresa id 1). Pra
// qualquer outra empresa que ainda não preencheu site/whatsapp/telefone/e-mails em Minha
// Empresa, o certo é mostrar vazio/nada, nunca o contato de outra empresa. Sem empresa nenhuma
// carregada (window._empresa null — preview sem login, ambiente de teste), trata como padrão
// (mesmo comportamento de sempre) só pra esses casos sem contexto real nenhum.
function ehEmpresaPromarking() { return !window._empresa || window._empresa.id === 1; }
// pedido do usuário (varredura de vazamento PRO Marking): "Código PMK" é a sigla interna de peça
// da PRO Marking (fornecedor/catálogo próprio) — aparecia sem nenhuma adaptação em toda tela e
// PDF de peças fornecidas/utilizadas, pra qualquer empresa. Rótulo genérico pra quem não é a PRO
// Marking.
function rotuloCodigoPeca() { return ehEmpresaPromarking() ? 'Código PMK' : 'Código da peça'; }
function empresaNome() { return (window._empresa && window._empresa.nome) || 'PRO Marking'; }
function empresaSite() { return (window._empresa && window._empresa.site) || (ehEmpresaPromarking() ? 'promarking.com.br' : ''); }
function empresaWhatsapp() { return (window._empresa && window._empresa.whatsapp) || (ehEmpresaPromarking() ? '12 99718-7506' : ''); }
function empresaTelefone() { return (window._empresa && window._empresa.telefone) || (ehEmpresaPromarking() ? '12 3902-3453' : ''); }
function empresaEmails() {
  if (window._empresa && Array.isArray(window._empresa.emails) && window._empresa.emails.length) return window._empresa.emails;
  return ehEmpresaPromarking() ? ['suporte@promarking.com.br', 'atendimento@promarking.com.br', 'tecnico@promarking.com.br', 'posvenda@promarking.com.br'] : [];
}
// bloco HTML de contato (WhatsApp/Telefone/E-mail) pros painéis "Sobre o equipamento" nas telas
// de preenchimento (Laudo Técnico, Corretiva etc.) — nunca mostra linha vazia nem herda contato
// de outra empresa (pedido do usuário: "No aceite de entrega aparece coisas da Promarking").
function blocoContatoHtml(limiteEmails) {
  const linhaTel = [
    empresaWhatsapp() && `<b>WhatsApp:</b> ${empresaWhatsapp()}`,
    empresaTelefone() && `<b>Telefone:</b> ${empresaTelefone()}`,
  ].filter(Boolean).join(' &nbsp; ');
  const emails = limiteEmails ? empresaEmails().slice(0, limiteEmails) : empresaEmails();
  const linhaEmail = emails.length ? `<b>E-mail:</b> ${emails.join(' / ')}` : '';
  return [linhaTel, linhaEmail].filter(Boolean).join('<br>');
}

