// pelo Termo de Aceite (ver relatorioAceitePadrao).
async function carregarSugestoesEquipamento() {
  try {
    return await api('/api/relatorios-manutencao/sugestoes-equipamento');
  } catch (e) {
    return { equipamentos: [], checklist_anterior: [] };
  }
}
// campo de equipamento digitável com sugestão (igual ideia do campoClienteHTML, mas sem id pra
// resolver — equipamento aqui é só texto livre, nunca trava no que já foi digitado antes).
function campoEquipamentoHTML(idPrefix, valorAtual, sugestoes, extraAttrs) {
  return `
    <input id="${idPrefix}" list="${idPrefix}-lista" value="${esc(valorAtual)}" ${extraAttrs || ''}>
    <datalist id="${idPrefix}-lista">${(sugestoes || []).map((s) => `<option value="${esc(s)}">`).join('')}</datalist>`;
}

// o service worker não enxerga o localStorage da página (mundos separados) — pra conseguir
// responder uma mensagem do chat interno direto pela notificação, sem abrir o app, ele precisa
// do token de um jeito que também dê pra ler de lá. Mesmo banco/loja que o sw.js usa (ver
// obterTokenSalvo em sw.js) — só a página escreve, só o service worker lê.
function abrirTokenSWDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('proconecta-sw', 1);
    req.onupgradeneeded = () => req.result.createObjectStore('auth');
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function salvarTokenSW(token) {
  try {
    const db = await abrirTokenSWDB();
    await new Promise((resolve, reject) => {
      const tx = db.transaction('auth', 'readwrite');
      const store = tx.objectStore('auth');
      if (token) store.put(token, 'token'); else store.delete('token');
      tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
    });
  } catch (e) { /* sem IndexedDB — resposta pela notificação simplesmente não funciona */ }
}

async function fazerLogin() {
  const email = document.getElementById('login-email').value;
  const senha = document.getElementById('login-senha').value;
  const erroEl = document.getElementById('login-erro');
  erroEl.classList.add('hidden');
  try {
    const data = await api('/api/login', { method: 'POST', body: { email, senha } });
    TOKEN = data.token;
    USER = data.usuario;
    localStorage.setItem('pc_token', TOKEN);
    salvarTokenSW(TOKEN);
    entrarNoApp();
  } catch (e) {
    erroEl.textContent = e.message;
    erroEl.classList.remove('hidden');
  }
}

// SaaS, passo 1: cadastro/trial self-service — link "Ainda não é cliente?" na própria tela de
// login alterna pro formulário de criar conta, sem precisar do Super Admin.
function mostrarFormCadastroSelfService() {
  document.getElementById('login-form-wrap').style.display = 'none';
  document.getElementById('cadastro-form-wrap').style.display = 'block';
}

function mostrarFormLoginNovamente() {
  document.getElementById('cadastro-form-wrap').style.display = 'none';
  document.getElementById('login-form-wrap').style.display = 'block';
}

async function cadastrarSelfService() {
  const body = {
    nome_empresa: document.getElementById('cad-empresa').value,
    nome: document.getElementById('cad-nome').value,
    email: document.getElementById('cad-email').value,
    senha: document.getElementById('cad-senha').value,
  };
  const erroEl = document.getElementById('cadastro-erro');
  erroEl.classList.add('hidden');
  try {
    const data = await api('/api/cadastro', { method: 'POST', body });
    TOKEN = data.token;
    USER = data.usuario;
    localStorage.setItem('pc_token', TOKEN);
    salvarTokenSW(TOKEN);
    entrarNoApp();
  } catch (e) {
    erroEl.textContent = e.message;
    erroEl.classList.remove('hidden');
  }
}

// esconde a tela de "carregando..." (só a logo) e mostra o formulário de login — chamada tanto
// depois de um logout quanto quando descobrimos (ao abrir o app) que não tem sessão salva ou
// que ela não é mais válida.
function mostrarTelaLogin() {
  const splash = document.getElementById('splashView');
  if (splash) splash.style.display = 'none';
  document.getElementById('appView').style.display = 'none';
  document.getElementById('authView').style.display = 'flex';
  mostrarFormLoginNovamente();
}

function sair() {
  TOKEN = null; USER = null; navAbertos = new Set();
  if (sinoTimer) clearInterval(sinoTimer);
  desmontarWidgetChatInterno();
  localStorage.removeItem('pc_token');
  localStorage.removeItem('pc_ultima_pagina');
  salvarTokenSW(null);
  mostrarTelaLogin();
  const empresaTag = document.getElementById('empresaTag');
  if (empresaTag) empresaTag.textContent = '';
  carregarEmpresa();
}

async function tentarSessaoExistente() {
  // pedido do usuário (pacote "Climatização / PMOC", Fase 5, item 6): "Sem login: página pública
  // mínima com a data da última manutenção e o nome da empresa" — diferente do QR de equipamento
  // núcleo (que sempre exige login), esse aqui precisa funcionar SEM sessão nenhuma, então é
  // tratado antes até de decidir se mostra a tela de login. Com sessão já aberta, o parâmetro
  // continua na URL e é tratado dentro de entrarNoApp() (mesmo padrão do `?qr=` ali).
  const pmocQrToken = new URLSearchParams(window.location.search).get('pmoc_qr');
  if (pmocQrToken && !TOKEN) {
    try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {}
    mostrarPaginaPublicaPmocQr(pmocQrToken);
    return;
  }
  // sem token salvo, nem vale a pena esperar: mostra o login na hora, em vez de deixar a tela
  // de "carregando..." parada à toa.
  if (!TOKEN) { mostrarTelaLogin(); return; }
  try {
    const data = await api('/api/me');
    USER = data.usuario;
    salvarTokenSW(TOKEN);
    entrarNoApp();
  } catch (e) {
    TOKEN = null; localStorage.removeItem('pc_token');
    mostrarTelaLogin();
  }
}

// página pública mínima do QR de um aparelho PMOC, pra quem escaneia sem estar logado (ver
// tentarSessaoExistente acima) — respeita o toggle configurável da empresa (ver PUT /api/pmoc/config).
async function mostrarPaginaPublicaPmocQr(token) {
  const splash = document.getElementById('splashView');
  if (splash) splash.style.display = 'none';
  document.getElementById('authView').style.display = 'none';
  document.getElementById('appView').style.display = 'none';
  let view = document.getElementById('pmocQrPublicoView');
  if (!view) {
    view = document.createElement('div');
    view.id = 'pmocQrPublicoView';
    view.style.cssText = 'min-height:100vh; display:flex; align-items:center; justify-content:center; padding:24px; text-align:center;';
    document.body.appendChild(view);
  }
  view.innerHTML = '<p>Carregando...</p>';
  try {
    const resposta = await fetch('/api/pmoc/qr/' + token + '/publico');
    const dados = await resposta.json();
    if (!resposta.ok || !dados.exibir) {
      view.innerHTML = '<div><h2>Informação não disponível</h2><p style="color:#888;">Esse QR Code não está habilitado para exibição pública.</p></div>';
      return;
    }
    view.innerHTML = `
      <div>
        <h2>${esc(dados.empresa_nome || 'Manutenção de climatização')}</h2>
        <p>${dados.ultima_manutencao ? 'Última manutenção registrada: <b>' + esc(fmtDataIsoAgendaRef(dados.ultima_manutencao)) + '</b>' : 'Nenhuma manutenção registrada ainda.'}</p>
      </div>`;
  } catch (e) {
    view.innerHTML = '<p>Não foi possível carregar essas informações agora.</p>';
  }
}

// ---------- fila de envio offline (relatórios do técnico) ----------
// quando o técnico conclui um relatório sem internet, o envio é guardado no aparelho (com
// fotos e tudo — por isso IndexedDB, não localStorage, que tem pouco espaço) em vez de dar
// erro. Assim que a conexão voltar (evento 'online', abrir o app de novo, ou tocar em
// Sincronizar) a fila é reenviada sozinha, na ordem em que foi criada.
const IDB_NOME = 'proconecta_offline';
const IDB_STORE = 'fila_visitas';
const MSG_ENFILEIRADO = 'Sem conexão no momento — o relatório foi guardado neste aparelho e será enviado automaticamente assim que a internet voltar (ou toque em Sincronizar).';

function abrirFilaOfflineDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(IDB_NOME, 1);
    req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains(IDB_STORE)) req.result.createObjectStore(IDB_STORE, { keyPath: 'id' }); };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function filaOfflineAdicionar(item) {
  const db = await abrirFilaOfflineDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, 'readwrite');
    tx.objectStore(IDB_STORE).put(item);
    tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
  });
}
async function filaOfflineListar() {
  const db = await abrirFilaOfflineDB();
  return new Promise((resolve, reject) => {
    const req = db.transaction(IDB_STORE, 'readonly').objectStore(IDB_STORE).getAll();
    req.onsuccess = () => resolve((req.result || []).sort((a, b) => a.criado_em.localeCompare(b.criado_em)));
    req.onerror = () => reject(req.error);
  });
}
async function filaOfflineRemover(id) {
  const db = await abrirFilaOfflineDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, 'readwrite');
    tx.objectStore(IDB_STORE).delete(id);
    tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
  });
}

// fetch() lança TypeError quando não há rede (sem chegar a ter resposta do servidor); erros
// vindos do backend (validação, 403...) chegam como Error normal com mensagem própria — só o
// primeiro caso deve cair na fila offline, o segundo é um erro de verdade pra tela tratar.
function ehErroDeConexao(e) { return e instanceof TypeError; }

// tenta enviar o relatório; se falhar por falta de conexão, guarda na fila em vez de propagar
// o erro. `extra` carrega o que for preciso pra terminar o pós-processamento (PDF/e-mail) do
// termo de aceite quando esse item sincronizar mais tarde. Falhas transitórias do servidor já
// são reprocessadas sozinhas dentro de api().
async function enviarVisitaOuEnfileirar(body, extra) {
  try {
    const resp = await api('/api/visitas', { method: 'POST', body });
    return { enviado: true, visita: resp.visita };
  } catch (e) {
    if (!ehErroDeConexao(e)) throw e;
    await filaOfflineAdicionar({ id: 'off-' + Date.now() + '-' + Math.random().toString(36).slice(2), body, criado_em: new Date().toISOString(), ...(extra || {}) });
    await atualizarBadgeSincronizar();
    return { enviado: false, enfileirado: true };
  }
}

let sincronizandoFilaOffline = false;
async function sincronizarFilaOffline() {
  if (sincronizandoFilaOffline || !TOKEN) return;
  if (!('indexedDB' in window)) return;
  let fila;
  try { fila = await filaOfflineListar(); } catch (e) { return; }
  if (!fila.length) return;
  sincronizandoFilaOffline = true;
  let enviados = 0;
  for (const item of fila) {
    try {
      const resp = await api('/api/visitas', { method: 'POST', body: item.body });
      await filaOfflineRemover(item.id);
      if (item.chaveRascunho) { localStorage.removeItem(item.chaveRascunho); apagarRascunhoServidor(item.chaveRascunho); }
      if (item.pdfTermoAceite && resp.visita) {
        try {
          const pdfDataUri = gerarPdfRelatorio(item.pdfTermoAceite.dados, item.pdfTermoAceite.agendaItem);
          const pdfBase64 = pdfDataUri.split(',')[1];
          await api(`/api/visitas/${resp.visita.id}/enviar-relatorio`, { method: 'POST', body: { pdf_base64: pdfBase64, emails: item.pdfTermoAceite.emails } });
        } catch (e2) { console.error('PDF/e-mail do relatório sincronizado depois falhou:', e2.message); }
      }
      enviados++;
    } catch (e) {
      if (ehErroDeConexao(e)) break; // sem rede de novo — tenta o resto na próxima
      console.error('Descartando item pendente que o servidor rejeitou:', e.message);
      await filaOfflineRemover(item.id);
    }
  }
  sincronizandoFilaOffline = false;
  await atualizarBadgeSincronizar();
  if (enviados > 0) {
    mostrarToast(`${enviados} relatório${enviados === 1 ? '' : 's'} pendente${enviados === 1 ? '' : 's'} sincronizado${enviados === 1 ? '' : 's'} com sucesso.`);
    if (paginaAtual === 'agenda') renderAgenda();
  }
}

async function atualizarBadgeSincronizar() {
  const badge = document.getElementById('sync-badge');
  if (!badge) return;
  if (!('indexedDB' in window)) { badge.classList.add('hidden'); return; }
  let fila = [];
  try { fila = await filaOfflineListar(); } catch (e) {}
  badge.textContent = fila.length;
  badge.classList.toggle('hidden', fila.length === 0);
}

window.addEventListener('online', sincronizarFilaOffline);

// ---------- notificação push (barra de notificação do celular) ----------
// pede permissão ao navegador e inscreve este aparelho pra receber notificação de verdade
// (O.S. atribuída, cliente confirmou, técnico a caminho) mesmo com o app fechado. Silencioso:
// se o navegador não suportar, ou a pessoa negar a permissão, o app continua funcionando
// normalmente — só sem a notificação na barra (o sino dentro do app continua funcionando).
function urlBase64ParaUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const bruto = atob(base64);
  const saida = new Uint8Array(bruto.length);
  for (let i = 0; i < bruto.length; i++) saida[i] = bruto.charCodeAt(i);
  return saida;
}

async function ativarNotificacoesPush() {
  try {
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) return;
    if (Notification.permission === 'denied') return;
    const registration = await navigator.serviceWorker.ready;
    let inscricao = await registration.pushManager.getSubscription();
    if (!inscricao) {
      const permissao = await Notification.requestPermission();
      if (permissao !== 'granted') return;
      const { chave } = await api('/api/push/chave-publica');
      inscricao = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ParaUint8Array(chave),
      });
    }
    const json = inscricao.toJSON();
    await api('/api/push/inscrever', { method: 'POST', body: { endpoint: json.endpoint, keys: json.keys } });
  } catch (e) { /* notificação push é um extra — nunca deve travar o login */ }
}

function entrarNoApp() {
  const splash = document.getElementById('splashView');
  if (splash) splash.style.display = 'none';
  document.getElementById('authView').style.display = 'none';
  document.getElementById('appView').style.display = 'block';
  if (USER.empresa) window._empresa = USER.empresa;
  aplicarMarcaNaTela();
  const empresaTag = document.getElementById('empresaTag');
  if (empresaTag) empresaTag.textContent = USER.empresa ? USER.empresa.nome : (USER.papel === 'super_admin' ? 'Painel da plataforma' : '');
  montarSidebar();
  atualizarSino();
  sinoTimer = setInterval(atualizarSino, 15000);
  atualizarBadgeSincronizar();
  sincronizarFilaOffline();
  montarWidgetChatInterno();
  if (['suporte', 'administrador', 'producao', 'cliente', 'pos_venda', 'estoque', 'gerente_loja', 'coordenador_tecnico', 'consultor_mercado'].includes(USER.papel)) ativarNotificacoesPush();
  // pedido do usuário (referência: app concorrente iClima) — administrador que acabou de
  // cadastrar uma empresa do perfil Refrigeração e ainda não concluiu o onboarding (ver
  // onboardingRefrigeracaoPendente) sempre cai aqui primeiro, nunca na página inicial normal do
  // papel — roda de novo a cada login até ser concluído, não só na primeira vez de verdade.
  if (onboardingRefrigeracaoPendente()) { ir('onboarding-refrigeracao'); return; }
  const primeiraPaginaPermitida = (function primeiraPagina(nodes) {
    for (const node of nodes) {
      if (node.page) return node.page;
      if (node.children) { const p = primeiraPagina(node.children); if (p) return p; }
    }
    return null;
  })(navDoUsuario());
  // pedido do usuário: "coloque como menu inicial ao logar vai abrir sempre nele" — Home (o antigo
  // "Indicadores (KPIs)") é a página de entrada de administrador/supervisor, os dois papéis que têm
  // acesso a ela (ver exigirPapel em GET /api/kpis no servidor).
  // pedido do usuário: "toda vez que loga abre o menu home [kpis-dashboard, que] é do acesso
  // PRO Marking [...] coloque pra abrir o início da própria empresa logada" — kpis-dashboard é a
  // Home do núcleo normal (indicadores/equipe), mas numa empresa do perfil Refrigeração essa não é
  // nem a página de entrada esperada (lá quem abre é "Início", ver home-refrigeracao) nem
  // necessariamente uma página que a empresa tem acesso (kpis-dashboard também exige o módulo
  // equipe_avancado — ver NAV.administrador acima). Pra administrador/supervisor dessas empresas,
  // usa Início no lugar de Home.
  const paginaInicial = (perfilRefrigeracaoAtivo() && (USER.papel === 'administrador' || USER.papel === 'supervisor'))
    ? 'home-refrigeracao'
    : { administrador: 'kpis-dashboard', supervisor: 'kpis-dashboard', cliente: 'biblioteca-defeitos', producao: 'biblioteca-defeitos', pos_venda: 'fila-pos-venda', estoque: 'fila-estoque' }[USER.papel] || primeiraPaginaPermitida || 'agenda';
  // ao recarregar/sincronizar a página (location.reload), volta pro menu onde o usuário estava
  // em vez de sempre abrir a página inicial do papel — só usa a última página salva se ela
  // ainda existir no menu deste usuário (evita cair numa página que um menu removido apagou).
  // Home/Início são exceção: "sempre" abrem nela, por isso não entram nessa restauração (home-
  // refrigeracao é o "Início" equivalente do perfil Refrigeração — ver paginaInicial acima).
  let paginaAoAbrir = paginaInicial;
  if (paginaInicial !== 'kpis-dashboard' && paginaInicial !== 'home-refrigeracao') {
    try {
      const ultima = localStorage.getItem('pc_ultima_pagina');
      if (ultima && buscarCaminho(navDoUsuario(), ultima, [])) paginaAoAbrir = ultima;
    } catch (e) {}
  }
  // volta do redirect de autorização do Outlook (ver GET /api/outlook/callback em server.js) —
  // a Microsoft manda o navegador de volta pra "/" com esse parâmetro na URL, não pra uma página
  // específica do app (o app não tem roteamento por URL); detecta aqui e abre a tela certa.
  const paramsUrl = new URLSearchParams(window.location.search);
  const outlookResultado = paramsUrl.get('outlook');
  if (outlookResultado && buscarCaminho(navDoUsuario(), 'agendamentos-outlook', [])) {
    paginaAoAbrir = 'agendamentos-outlook';
  }
  // QR Code do equipamento (versão Restaurantes/rede multiunidade, Fase 1 — Base, seção 5 do
  // pedido do usuário): "exige login. Sem login, mostra só a tela de entrada" — como entrarNoApp
  // só roda DEPOIS do login (ver fazerLogin), o próprio fluxo normal já garante isso: sem login, a
  // pessoa fica na tela de entrada (authView) e nunca chega aqui; o parâmetro continua na URL e é
  // tratado assim que o login completa.
  const qrToken = paramsUrl.get('qr');
  if (qrToken) {
    try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {}
    abrirEquipamentoPorQr(qrToken);
    return;
  }
  // QR de aparelho do pacote PMOC (Fase 5, item 6) — mesma ideia do `?qr=` acima, só que já
  // logado: quem escaneou SEM login caiu em mostrarPaginaPublicaPmocQr antes de chegar aqui (ver
  // tentarSessaoExistente), então se o código chegou até este ponto é porque TOKEN já existe.
  const pmocQrTokenLogado = paramsUrl.get('pmoc_qr');
  if (pmocQrTokenLogado) {
    try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {}
    abrirAparelhoPorQrPmoc(pmocQrTokenLogado);
    return;
  }
  ir(paginaAoAbrir);
  if (outlookResultado === 'conectado') mostrarToast('Conta do Outlook conectada.');
  else if (outlookResultado === 'erro') mostrarToast('Não consegui conectar com o Outlook: ' + (paramsUrl.get('msg') || 'tente de novo.'));
  if (outlookResultado) { try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {} }
}

function initials(nome) {
  return (nome || '?').trim().split(/\s+/).slice(0, 2).map((p) => p[0]).join('').toUpperCase();
}

function renderHeaderRight() {
  const el = document.getElementById('headerRight');
  el.innerHTML = `
    ${USER.papel === 'suporte' ? `
    <button class="btn-presenca ${USER.online ? 'online' : 'offline'}" id="btn-presenca" onclick="alternarPresenca()" title="Ficar online pra receber atendimentos na fila">
      <span class="presenca-bolinha"></span><span class="presenca-label">${USER.online ? 'Online' : 'Offline'}</span>
    </button>` : ''}
    <div class="user-chip" onclick="abrirMeuPerfil()" title="Meu perfil — alterar e-mail/senha" style="cursor:pointer;">
      <div class="user-avatar">${initials(USER.nome)}</div>
      <div class="user-meta">
        <span class="u-name">${esc(USER.nome)}</span>
        <span class="u-role">${PAPEL_LABEL[USER.papel] || USER.papel}</span>
      </div>
    </div>
    <button class="btn-bell" id="btn-sync" onclick="sincronizarApp()" title="Sincronizar — buscar as atualizações mais recentes">
      <svg width="19" height="19" viewBox="0 0 24 24" fill="none"><path d="M20 11A8.1 8.1 0 0 0 4.5 9M4 5v4h4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M4 13a8.1 8.1 0 0 0 15.5 2M20 19v-4h-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <span class="bell-badge hidden" id="sync-badge">0</span>
    </button>
    <div class="bell-wrap">
      <button class="btn-bell" id="btn-bell" onclick="alternarSino()">
        <svg width="19" height="19" viewBox="0 0 24 24" fill="none"><path d="M12 3a6 6 0 0 0-6 6v3.3c0 .6-.2 1.2-.6 1.7L4 16h16l-1.4-2a2.6 2.6 0 0 1-.6-1.7V9a6 6 0 0 0-6-6Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M9.5 19a2.5 2.5 0 0 0 5 0" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
        <span class="bell-badge hidden" id="bell-badge">0</span>
      </button>
      <div class="bell-panel" id="bell-panel"></div>
    </div>
    <button class="btn-logout" onclick="sair()" title="Sair">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M16 17l5-5-5-5M21 12H9" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <span class="btn-logout-label">Sair</span>
    </button>
  `;
}

// pedido do usuário: "coloque opção de o próprio usuário alterar seu email e senha" — modal aberto
// ao clicar no próprio chip de usuário no cabeçalho (até então só decorativo). Pede a senha atual
// pra confirmar qualquer mudança (ver PUT /api/me no servidor), mesmo padrão de modal dinâmico
// já usado em abrirEncaminharRelatorioManutencao (cria o container uma vez, reusa depois).
function abrirMeuPerfil() {
  let modal = document.getElementById('modal-meu-perfil');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'modal-meu-perfil';
    modal.className = 'modal-overlay';
    document.body.appendChild(modal);
  }
  modal.classList.add('show');
  const fechar = () => modal.classList.remove('show');
  modal.innerHTML = `
    <div class="modal-card" style="max-width:420px;">
      <h3>Meu perfil</h3>
      <p>Altere seu e-mail e/ou sua senha de acesso. Informe a senha atual pra confirmar.</p>
      <div class="field"><label>E-mail</label><input id="mp-email" value="${esc(USER.email || '')}"></div>
      <div class="field"><label>Nova senha (deixe em branco pra não alterar)</label><input id="mp-senha-nova" type="password" placeholder="Mínimo 6 caracteres" autocomplete="new-password"></div>
      <div class="field"><label>Confirmar nova senha</label><input id="mp-senha-confirma" type="password" autocomplete="new-password"></div>
      <div class="field"><label>Senha atual*</label><input id="mp-senha-atual" type="password" autocomplete="current-password"></div>
      <button class="btn btn-primary" id="mp-btn-salvar" style="width:100%; justify-content:center; margin-top:6px;">Salvar alterações</button>
      <button class="btn-outline-sm" id="mp-btn-cancelar" style="width:100%; justify-content:center; margin-top:10px;">Cancelar</button>
    </div>`;
  modal.querySelector('#mp-btn-cancelar').onclick = fechar;
  modal.querySelector('#mp-btn-salvar').onclick = async () => {
    const email = document.getElementById('mp-email').value.trim();
    const senhaNova = document.getElementById('mp-senha-nova').value;
    const senhaConfirma = document.getElementById('mp-senha-confirma').value;
    const senhaAtual = document.getElementById('mp-senha-atual').value;
    if (!email || !email.includes('@')) return alert('Informe um e-mail válido.');
    if (senhaNova && senhaNova.length < 6) return alert('A nova senha precisa ter pelo menos 6 caracteres.');
    if (senhaNova && senhaNova !== senhaConfirma) return alert('A confirmação não bate com a nova senha.');
    if (!senhaAtual) return alert('Informe sua senha atual pra confirmar a alteração.');
    const btn = modal.querySelector('#mp-btn-salvar');
    btn.disabled = true; btn.textContent = 'Salvando...';
    try {
      const body = { email, senha_atual: senhaAtual };
      if (senhaNova) body.senha_nova = senhaNova;
      const { usuario } = await api('/api/me', { method: 'PUT', body });
      USER.email = usuario.email;
      fechar();
      mostrarToast('Perfil atualizado.');
    } catch (e) {
      alert('Erro ao salvar: ' + e.message);
    } finally {
      btn.disabled = false; btn.textContent = 'Salvar alterações';
    }
  };
}

// liga/desliga a presença do técnico na fila de atendimento — só quem está online entra
// no rodízio (round-robin) que distribui os atendimentos novos.
async function alternarPresenca() {
  const btn = document.getElementById('btn-presenca');
  if (btn) btn.disabled = true;
  try {
    const { usuario } = await api('/api/tecnico/online', { method: 'POST', body: { online: !USER.online } });
    USER.online = usuario.online;
    USER.online_desde = usuario.online_desde;
    renderHeaderRight();
  } catch (e) { alert('Erro: ' + e.message); }
  finally { if (btn) btn.disabled = false; }
}

// força buscar a versão mais nova do sistema e dos dados — útil no app instalado (PWA),
// que pode ficar aberto em segundo plano por dias sem recarregar sozinho.
function sincronizarApp() {
  const btn = document.getElementById('btn-sync');
  if (btn) btn.classList.add('girando');
  location.reload();
}

