// ---- FMEA: Ranking RPN e Pareto de falhas (passo 5) ----
// Ranking: reaproveita o próprio GET /api/fmea/modos-falha (já enriquecido no servidor com
// componente_nome/catalogo_tipo/catalogo_modelo/ocorrencias_reais — ver server.js,
// modosFalhaEnriquecidos) sem filtro de componente, e ordena por RPN decrescente no cliente — não
// precisou de outro endpoint só pra isso. Pareto: usa o endpoint novo /api/fmea/pareto, que conta
// falhas de verdade (laudos técnicos com a cascata FMEA preenchida), com toggle componente/equipamento.
let _fmeaParetoAgrupamento = 'componente';
async function renderFmeaRelatorios() {
  const { modos_falha } = await api('/api/fmea/modos-falha');
  const ranking = [...modos_falha].sort((a, b) => b.rpn - a.rpn);
  const main = document.getElementById('main');
  main.innerHTML = `
    <div class="page-head" style="display:flex; justify-content:space-between; align-items:flex-end; flex-wrap:wrap; gap:10px;">
      <div><h1>FMEA — Ranking e Pareto</h1><p>Ranking de risco (RPN) do catálogo cadastrado e Pareto das falhas que realmente aconteceram nos laudos técnicos.</p></div>
      ${botaoVoltarEquipamentosMenu()}
    </div>
    <div class="panel"><div class="panel-head">Ranking por RPN (Severidade × Ocorrência × Detecção)</div>
      <table>
        <tr><th>Modelo</th><th>Componente</th><th>Modo de falha</th><th>S</th><th>O</th><th>D</th><th>RPN</th><th>Ocorrências reais</th></tr>
        ${ranking.length ? ranking.map((m) => `
          <tr>
            <td data-label="Modelo">${esc(m.catalogo_tipo)} ${esc(m.catalogo_modelo)}</td>
            <td data-label="Componente">${esc(m.componente_nome)}</td>
            <td data-label="Modo de falha">${esc(m.nome)}</td>
            <td data-label="S">${m.severidade}</td><td data-label="O">${m.ocorrencia}</td><td data-label="D">${m.deteccao}</td>
            <td data-label="RPN"><b>${m.rpn}</b></td>
            <td data-label="Ocorrências reais">${m.ocorrencias_reais}</td>
          </tr>`).join('') : `<tr><td colspan="8" class="empty">Nenhum modo de falha cadastrado ainda.</td></tr>`}
      </table>
    </div>
    <div class="panel">
      <div class="panel-head" style="display:flex; justify-content:space-between; align-items:center;">
        <span>Pareto de falhas</span>
        <div>
          <button class="btn-outline-sm" id="fmea-pareto-btn-componente" onclick="trocarParetoAgrupamento('componente')">Por componente</button>
          <button class="btn-outline-sm" id="fmea-pareto-btn-equipamento" onclick="trocarParetoAgrupamento('equipamento')">Por equipamento</button>
        </div>
      </div>
      <p style="color:var(--ink-soft); font-size:13px; margin-top:-8px;">Conta cada laudo técnico que teve a classificação de falha (RCM/FMEA) preenchida — os ~20% que respondem pela maior parte das falhas aparecem no topo.</p>
      <div id="fmea-pareto-area"><div class="empty">Carregando...</div></div>
    </div>`;
  _fmeaParetoAgrupamento = 'componente';
  renderFmeaParetoArea();
}
async function trocarParetoAgrupamento(modo) {
  _fmeaParetoAgrupamento = modo;
  renderFmeaParetoArea();
}
async function renderFmeaParetoArea() {
  const btnComponente = document.getElementById('fmea-pareto-btn-componente');
  const btnEquipamento = document.getElementById('fmea-pareto-btn-equipamento');
  const estiloAtivo = { background: 'var(--blue)', color: '#fff', borderColor: 'var(--blue)' };
  const estiloInativo = { background: '#fff', color: 'var(--ink-soft)', borderColor: 'var(--line)' };
  Object.assign(btnComponente.style, _fmeaParetoAgrupamento === 'componente' ? estiloAtivo : estiloInativo);
  Object.assign(btnEquipamento.style, _fmeaParetoAgrupamento === 'equipamento' ? estiloAtivo : estiloInativo);
  const area = document.getElementById('fmea-pareto-area');
  area.innerHTML = `<div class="empty">Carregando...</div>`;
  const { pareto, total } = await api(`/api/fmea/pareto?agrupar_por=${_fmeaParetoAgrupamento}`);
  if (!total) { area.innerHTML = `<div class="empty">Nenhuma falha classificada em laudos técnicos ainda.</div>`; return; }
  area.innerHTML = `
    <table>
      <tr><th>${_fmeaParetoAgrupamento === 'componente' ? 'Componente' : 'Equipamento'}</th><th>Qtd.</th><th>%</th><th>% acumulado</th><th></th></tr>
      ${pareto.map((p) => `
        <tr>
          <td data-label="${_fmeaParetoAgrupamento === 'componente' ? 'Componente' : 'Equipamento'}">${esc(p.label)}</td>
          <td data-label="Qtd.">${p.qtd}</td>
          <td data-label="%">${p.percentual}%</td>
          <td data-label="% acumulado">${p.percentual_acumulado}%</td>
          <td style="min-width:120px;"><div style="background:var(--line); border-radius:4px; height:8px;"><div style="background:var(--blue-bright); border-radius:4px; height:8px; width:${p.percentual}%;"></div></div></td>
        </tr>`).join('')}
    </table>`;
}

// ---- Dashboard de KPIs (RCM/SAP PM, Fase 1, passos 6-7) ----
// MTBF, MTTR, disponibilidade, backlog, %preventiva×corretiva, filtros (período/cliente/
// equipamento/técnico) e gráficos mensais — tudo calculado no servidor (GET /api/kpis e GET
// /api/kpis/mensal, funções calcularKpis/calcularKpisMensais em server.js) a partir das datas/
// horas que já existem hoje nas O.S. e nos laudos técnicos, sem nenhuma tela ou campo novo de
// entrada de dados. Exportação Excel ainda não — isso é o passo 8.
let _kpisFiltros = {};
let _kpisChartTipos = null;
let _kpisChartMttr = null;
let _kpisChartDonut = null;
let _kpisMaoDeObraCache = null;
let _kpisChartMaoDeObra = null;

// pedido do usuário: "a data de filtro sempre será o início do mês atual e o final do mês atual" —
// usado toda vez que a tela Home (ex-KPIs) abre ou quando o admin limpa os filtros, pra nunca cair
// no "sem período" (que no backend significa "desde sempre", ver filtrarAgendaKpis em server.js).
function limitesMesAtualISO() {
  const hoje = new Date();
  const ano = hoje.getFullYear();
  const mes = hoje.getMonth();
  const ultimoDia = new Date(ano, mes + 1, 0).getDate();
  const mm = String(mes + 1).padStart(2, '0');
  return { inicio: `${ano}-${mm}-01`, fim: `${ano}-${mm}-${String(ultimoDia).padStart(2, '0')}` };
}

// pequeno "?" que só mostra uma explicação ao passar o cursor (pedido do usuário) — usa o atributo
// title nativo do navegador (tooltip no hover), sem lib nova. stopPropagation evita que um toque
// nele em tela sensível ao toque dispare o clique da tile por trás (que abre o drill-down).
function ajudaKpi(texto) {
  return `<span class="kpi-help" title="${esc(texto)}" onclick="event.stopPropagation()">?</span>`;
}

async function renderKpisDashboard() {
  const [{ clientes }, { equipamentos }, { usuarios }] = await Promise.all([
    api('/api/clientes'), api('/api/equipamentos'), api('/api/usuarios'),
  ]);
  const equipamentosAtrelados = equipamentos.filter((e) => e.cliente_id !== null);
  const tecnicos = usuarios.filter((u) => u.papel === 'suporte');

  // pedido do usuário: "a data de filtro padrão preenchido é do início ao fim do mês atual,
  // podendo ser modificado a depender do usuário" — o mês atual é só o PRÉ-PREENCHIMENTO inicial
  // (primeira vez que a Home abre nesta sessão, ou depois de "Limpar"); se o usuário já aplicou um
  // período diferente, essa escolha continua valendo ao navegar pra outra tela e voltar pra Home —
  // não é sobrescrita de novo a cada entrada na tela.
  if (!_kpisFiltros.periodo_inicio || !_kpisFiltros.periodo_fim) {
    const { inicio, fim } = limitesMesAtualISO();
    _kpisFiltros = { ..._kpisFiltros, periodo_inicio: inicio, periodo_fim: fim };
  }

  const main = document.getElementById('main');
  main.innerHTML = `
    <div class="page-head"><h1>Home</h1><p>Indicadores calculados a partir das datas/horas das Ordens de Serviço e dos Laudos Técnicos, no período selecionado abaixo.</p></div>
    <div class="filtros-row">
      <div class="field"><label>Período — de</label><input id="kf-periodo-inicio" type="date" value="${esc(_kpisFiltros.periodo_inicio || '')}"></div>
      <div class="field"><label>Período — até</label><input id="kf-periodo-fim" type="date" value="${esc(_kpisFiltros.periodo_fim || '')}"></div>
      <div class="field"><label>Cliente</label><select id="kf-cliente"><option value="">Todos</option>${clientes.map((c) => `<option value="${c.id}" ${String(_kpisFiltros.cliente_id) === String(c.id) ? 'selected' : ''}>${esc(c.nome_empresa)}</option>`).join('')}</select></div>
      <div class="field"><label>${t('equipamento', 'Equipamento')}</label><select id="kf-equipamento"><option value="">Todos</option>${equipamentosAtrelados.map((e) => `<option value="${e.id}" ${String(_kpisFiltros.equipamento_id) === String(e.id) ? 'selected' : ''}>${esc(e.tipo)} ${esc(e.modelo)}${e.numero_serie ? ` (${esc(e.numero_serie)})` : ''}</option>`).join('')}</select></div>
      <div class="field"><label>Técnico</label><select id="kf-tecnico"><option value="">Todos</option>${tecnicos.map((u) => `<option value="${u.id}" ${String(_kpisFiltros.tecnico_id) === String(u.id) ? 'selected' : ''}>${esc(u.nome)}</option>`).join('')}</select></div>
      <div class="field"><label>Contrato de manutenção</label><select id="kf-contrato">
        <option value="">Todos</option>
        <option value="com" ${_kpisFiltros.contrato === 'com' ? 'selected' : ''}>Com contrato</option>
        <option value="sem" ${_kpisFiltros.contrato === 'sem' ? 'selected' : ''}>Sem contrato</option>
      </select></div>
      <button class="btn btn-primary btn-sm" onclick="aplicarFiltrosKpis()">Aplicar filtros</button>
      <button class="btn-outline-sm" onclick="limparFiltrosKpis()">Limpar</button>
      <button class="btn-outline-sm" onclick="exportarKpisExcel()">Exportar Excel</button>
      <button class="btn-outline-sm" onclick="exportarKpisDashboardPdf()">Exportar dashboard (PDF)</button>
    </div>
    <div class="kpis-tiles" id="kpis-cards"><div class="empty">Carregando...</div></div>
    <div class="kpis-row-donut">
      <div class="panel" style="flex:0 0 260px; margin-bottom:0; display:flex; flex-direction:column;">
        <div class="panel-head"><span>Preventiva × Corretiva</span>${ajudaKpi('Proporção entre Ordens de Serviço do tipo Preventiva e Corretiva dentro do período e filtros selecionados.')}</div>
        <div style="flex:1; display:flex; align-items:center; justify-content:center; min-height:180px;">
          <canvas id="kpis-chart-donut" width="180" height="180"></canvas>
          <div id="kpis-donut-vazio" class="empty" style="display:none;">Sem O.S. preventiva/corretiva nesse recorte.</div>
        </div>
      </div>
      <div class="panel" style="flex:1; margin-bottom:0;">
        <div class="panel-head"><span>Preventiva × Corretiva por mês</span>${ajudaKpi('Quantidade de Ordens de Serviço Preventiva e Corretiva, mês a mês, dentro do recorte selecionado.')}</div>
        <canvas id="kpis-chart-tipos" height="90"></canvas>
      </div>
    </div>
    <div class="panel"><div class="panel-head"><span>Técnicos — O.S. concluídas no recorte atual</span>${ajudaKpi('Ranking dos técnicos pela quantidade de Ordens de Serviço concluídas dentro do período e filtros selecionados.')}</div><div id="kpis-ranking-tecnicos"><div class="empty">Carregando...</div></div></div>
    <div class="panel"><div class="panel-head"><span>MTTR por mês (horas)</span>${ajudaKpi('MTTR — Tempo Médio de Reparo (Mean Time To Repair): quantas horas, em média, leva do início ao fim do reparo de uma O.S. corretiva, mês a mês.')}</div><canvas id="kpis-chart-mttr" height="90"></canvas><p id="kpis-mttr-nota" style="display:none; margin:8px 0 0; font-size:12px; color:var(--ink-soft);">* mês em andamento — valor parcial, atualiza conforme os reparos avançam.</p></div>`;
  await atualizarKpisDashboard();
}

function filtrosKpisDaTela() {
  const periodoInicio = document.getElementById('kf-periodo-inicio').value;
  const periodoFim = document.getElementById('kf-periodo-fim').value;
  const clienteId = document.getElementById('kf-cliente').value;
  const equipamentoId = document.getElementById('kf-equipamento').value;
  const tecnicoId = document.getElementById('kf-tecnico').value;
  const contrato = document.getElementById('kf-contrato').value;
  return {
    ...(periodoInicio ? { periodo_inicio: periodoInicio } : {}),
    ...(periodoFim ? { periodo_fim: periodoFim } : {}),
    ...(clienteId ? { cliente_id: clienteId } : {}),
    ...(equipamentoId ? { equipamento_id: equipamentoId } : {}),
    ...(tecnicoId ? { tecnico_id: tecnicoId } : {}),
    ...(contrato ? { contrato } : {}),
  };
}
async function aplicarFiltrosKpis() {
  _kpisFiltros = filtrosKpisDaTela();
  await atualizarKpisDashboard();
}
async function limparFiltrosKpis() {
  // "Limpar" não some com o período — ele volta pro padrão (mês atual), só os outros filtros
  // (cliente/equipamento/técnico/contrato) ficam realmente vazios.
  const { inicio, fim } = limitesMesAtualISO();
  _kpisFiltros = { periodo_inicio: inicio, periodo_fim: fim };
  document.getElementById('kf-periodo-inicio').value = inicio;
  document.getElementById('kf-periodo-fim').value = fim;
  ['kf-cliente', 'kf-equipamento', 'kf-tecnico', 'kf-contrato'].forEach((id) => { document.getElementById(id).value = ''; });
  await atualizarKpisDashboard();
}

async function atualizarKpisDashboard() {
  const params = new URLSearchParams(_kpisFiltros).toString();
  const sufixo = params ? `?${params}` : '';
  const [{ kpis }, { meses }, { ranking }, maoDeObra] = await Promise.all([
    api(`/api/kpis${sufixo}`), api(`/api/kpis/mensal${sufixo}`), api(`/api/kpis/ranking-tecnicos${sufixo}`),
    api(`/api/kpis/mao-de-obra${sufixo}`),
  ]);
  _kpisMaoDeObraCache = maoDeObra;
  // Tiles coloridas (passo 3 da Opção F) — igual ao mockup aprovado: tile inteira clicável abre o
  // mesmo drill-down que o antigo botão "Ver detalhes" (passo 9) já abria. Disponibilidade ganha um
  // anel de progresso (SVG, sem lib nova) em vez de só o número.
  const ringSvg = (pct) => `
    <svg width="28" height="28" viewBox="0 0 36 36" style="flex-shrink:0;">
      <circle cx="18" cy="18" r="15" fill="none" stroke="rgba(255,255,255,.3)" stroke-width="4"/>
      <circle cx="18" cy="18" r="15" fill="none" stroke="#fff" stroke-width="4" stroke-dasharray="${Math.max(0, Math.min(100, pct))} 100" stroke-dashoffset="25" transform="rotate(-90 18 18)" pathLength="100" stroke-linecap="round"/>
    </svg>`;
  const tile = (titulo, valorHtml, cor, indicador, ajuda) => `
    <div class="kpis-tile" style="background:${cor};" onclick="abrirKpiDetalhe('${indicador}')">
      <div class="kpis-tile-label"><span>${esc(titulo)}</span>${ajuda ? ajudaKpi(ajuda) : ''}</div>
      ${valorHtml}
    </div>`;
  document.getElementById('kpis-cards').innerHTML = `
    ${tile('MTBF', `<div class="kpis-tile-valor">${kpis.mtbf_dias !== null ? `${kpis.mtbf_dias} d` : '—'}</div>`, 'var(--blue)', 'mtbf', 'MTBF — Tempo Médio Entre Falhas (Mean Time Between Failures): intervalo médio, em dias, entre o fim de um atendimento e o início do próximo nesse mesmo equipamento. Quanto maior, melhor (o equipamento quebra menos).')}
    ${tile('MTTR', `<div class="kpis-tile-valor">${kpis.mttr_horas !== null ? `${kpis.mttr_horas} h` : '—'}</div>`, 'var(--purple)', 'mttr', 'MTTR — Tempo Médio de Reparo (Mean Time To Repair): tempo médio, em horas, entre a entrada e a conclusão do reparo nos Laudos Técnicos. Quanto menor, mais rápido o reparo.')}
    ${tile('Disponibilidade', kpis.disponibilidade_percentual !== null
      ? `<div class="kpis-tile-valor-ring">${ringSvg(kpis.disponibilidade_percentual)}<span>${kpis.disponibilidade_percentual}%</span></div>`
      : `<div class="kpis-tile-valor">—</div>`, 'var(--green)', 'disponibilidade', 'Disponibilidade: percentual do tempo em que os equipamentos ficaram operando normalmente (fora de reparo), dentro do período e filtros selecionados.')}
    ${tile('Backlog', `<div class="kpis-tile-valor">${kpis.backlog_qtd} O.S.</div>`, 'var(--orange)', 'backlog', 'Backlog: quantidade de Ordens de Serviço ainda não finalizadas (em aberto) no recorte atual.')}
    ${tile('O.S. no recorte', `<div class="kpis-tile-valor">${kpis.total_os}</div>`, 'var(--amber)', 'total_os', 'O.S. no recorte: quantidade total de Ordens de Serviço abertas dentro do período e filtros selecionados.')}
    <div class="kpis-tile" style="background:var(--teal);" onclick="abrirMaoDeObraDetalhe()">
      <div class="kpis-tile-label"><span>MOD</span>${ajudaKpi('MOD — Mão de Obra: percentual de ocupação da equipe técnica (horas trabalhadas dividido pela jornada esperada) no período selecionado. Clique pra ver o detalhe por técnico.')}</div>
      ${maoDeObra.equipe.percentual_ocupacao !== null
        ? `<div class="kpis-tile-valor-ring">${ringSvg(maoDeObra.equipe.percentual_ocupacao)}<span>${maoDeObra.equipe.percentual_ocupacao}%</span></div>`
        : `<div class="kpis-tile-valor">—</div>`}
    </div>`;
  desenharGraficosKpis(meses, kpis);
  desenharRankingTecnicosKpis(ranking);
}

// ranking de técnicos por O.S. concluída (passo 2 da Opção F) — barra horizontal proporcional ao
// maior valor do recorte atual, mesmo padrão visual do mockup aprovado.
function desenharRankingTecnicosKpis(ranking) {
  const container = document.getElementById('kpis-ranking-tecnicos');
  if (!container) return;
  if (!ranking.length) {
    container.innerHTML = `<div class="empty">Nenhuma O.S. concluída nesse recorte.</div>`;
    return;
  }
  const maior = Math.max(...ranking.map((r) => r.qtd_os_concluidas));
  container.innerHTML = `
    <div style="display:flex; flex-direction:column; gap:9px;">
      ${ranking.map((r) => `
        <div style="display:flex; align-items:center; gap:10px;">
          <div style="width:140px; font-size:12.5px; font-weight:600; color:#1F2937; flex-shrink:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${esc(r.tecnico_nome)}</div>
          <div style="flex:1; background:var(--blue-pale); height:16px; border-radius:8px; overflow:hidden;"><div style="width:${Math.round((r.qtd_os_concluidas / maior) * 100)}%; background:var(--blue); height:16px;"></div></div>
          <div style="width:24px; font-size:12.5px; font-weight:700; color:var(--navy); text-align:right;">${r.qtd_os_concluidas}</div>
        </div>`).join('')}
    </div>`;
}

// ---------- KPI de Mão de Obra: horas trabalhadas × paradas por técnico ----------
// pedido do usuário: "Crie um indicador kpi de mão de obra, horas em que o técnico fica parado e
// trabalhando. Ao clicar abrir os dados individual de cada técnico e só clicar no técnico abrir
// as atividades." Clicar na tile do dashboard abre esta tela (resumo da equipe + por técnico);
// clicar num técnico aqui reaproveita a mesma tela de detalhe da Atividades do Dia (ver
// abrirDetalheAtividadesTecnico), só que voltando pra cá em vez de pra Atividades do Dia.
async function abrirMaoDeObraDetalhe() {
  const params = new URLSearchParams(_kpisFiltros).toString();
  const sufixo = params ? `?${params}` : '';
  const resp = _kpisMaoDeObraCache || await api(`/api/kpis/mao-de-obra${sufixo}`);
  _kpisMaoDeObraCache = resp;
  // a tela de detalhe por técnico (abrirDetalheAtividadesTecnico) é por mês — usa o mês do fim do
  // período deste KPI, pra abrir já no mês certo quando o admin clicar num técnico.
  atividadesEquipeMesAtual = resp.periodo.fim.slice(0, 7);
  const main = document.getElementById('main');
  main.innerHTML = `
    <div class="page-head" style="display:flex; justify-content:space-between; align-items:flex-end; flex-wrap:wrap; gap:10px;">
      <div><h1>MOD</h1><p>Horas trabalhadas × paradas por técnico, de ${fmtData(resp.periodo.inicio)} a ${fmtData(resp.periodo.fim)}. A jornada de referência é de ${resp.jornada_padrao_horas}h por dia útil. Horas de O.S. usam o deslocamento/chegada reais do técnico quando já registrados (não só o horário agendado) — quando um dia passa da jornada, o excedente vira saldo positivo que compensa dias de déficit dentro do mesmo período, e só o que sobra líquido depois dessa compensação conta como parado.</p></div>
      <button class="btn-outline-sm" onclick="ir('kpis-dashboard')">‹ Home</button>
    </div>
    <div class="kpis-row-donut">
      <div class="panel" style="flex:0 0 260px; margin-bottom:0; display:flex; flex-direction:column;">
        <div class="panel-head">Equipe — horas trabalhadas × paradas</div>
        <div style="flex:1; display:flex; align-items:center; justify-content:center; min-height:180px;">
          <canvas id="mdo-chart-donut" width="180" height="180"></canvas>
        </div>
      </div>
      <div class="panel" style="flex:1; margin-bottom:0;">
        <div class="panel-head">Por técnico — clique num nome pra ver as atividades dele</div>
        <div id="mdo-ranking"><div class="empty">Carregando...</div></div>
      </div>
    </div>`;
  desenharMaoDeObra(resp);
}

function desenharMaoDeObra(resp) {
  const { equipe, tecnicos } = resp;
  if (typeof Chart !== 'undefined') {
    if (_kpisChartMaoDeObra) _kpisChartMaoDeObra.destroy();
    const canvas = document.getElementById('mdo-chart-donut');
    // cores de status (não categóricas): verde = trabalhada (bom), âmbar = parada (atenção) — as
    // mesmas já usadas em Atividades do Dia pro status "concluído"/"pendente" de cada atividade.
    if (canvas) {
      _kpisChartMaoDeObra = new Chart(canvas, {
        type: 'doughnut',
        data: {
          labels: ['Trabalhadas', 'Paradas'],
          datasets: [{ data: [equipe.horas_trabalhadas, equipe.horas_paradas], backgroundColor: ['#198754', '#C7860A'], borderColor: '#fff', borderWidth: 2 }],
        },
        options: {
          responsive: true, cutout: '62%',
          plugins: {
            legend: { position: 'bottom', labels: { boxWidth: 10, padding: 12, font: { size: 11 } } },
            tooltip: { callbacks: { label: (ctx) => `${ctx.label}: ${ctx.raw} h` } },
          },
        },
      });
    }
  }

  const ranking = document.getElementById('mdo-ranking');
  if (!ranking) return;
  if (!tecnicos.length) {
    ranking.innerHTML = `<div class="empty">Nenhum técnico ativo nessa equipe.</div>`;
    return;
  }
  ranking.innerHTML = `
    <div style="margin-bottom:12px; font-size:13px; color:var(--ink-soft);">
      Equipe: <strong style="color:var(--ink);">${equipe.horas_trabalhadas}h trabalhadas</strong> × <strong style="color:var(--ink);">${equipe.horas_paradas}h paradas</strong>${equipe.horas_excedentes ? ` <span style="color:var(--teal); font-weight:700;">(+${equipe.horas_excedentes}h de saldo/colchão)</span>` : ''}${equipe.percentual_ocupacao !== null ? ` — ${equipe.percentual_ocupacao}% de ocupação` : ''}
    </div>
    <div style="display:flex; flex-direction:column; gap:12px;">
      ${tecnicos.map((t) => {
        // barra: ocupação líquida (já com o saldo de dias de sobra compensando dias de déficit)
        // até 100%; acima disso o excedente vira um selo à parte em vez de estourar a barra.
        const pctOcupacao = Math.max(0, Math.min(100, t.percentual_ocupacao ?? 0));
        const pctParada = 100 - pctOcupacao;
        const nomeEscapado = esc(t.tecnico_nome).replace(/'/g, '&#39;');
        return `
        <div class="viagens-chart-row clicavel" onclick="abrirDetalheAtividadesTecnico(${t.tecnico_id}, '${nomeEscapado}', 'abrirMaoDeObraDetalhe()')" style="flex-direction:column; align-items:stretch;">
          <div style="display:flex; justify-content:space-between; align-items:baseline; margin-bottom:4px; gap:8px;">
            <strong style="font-size:13px; color:var(--ink);">${esc(t.tecnico_nome)}</strong>
            <span style="font-size:12px; color:var(--ink-soft); white-space:nowrap;">
              ${t.percentual_ocupacao !== null ? `${t.percentual_ocupacao}% ocupação` : 'sem dados no período'}
              ${t.horas_excedentes ? ` <span style="color:var(--teal); font-weight:700;">+${t.horas_excedentes}h colchão</span>` : ''}
            </span>
          </div>
          <div style="display:flex; height:14px; border-radius:7px; overflow:hidden; background:var(--line);">
            ${pctOcupacao > 0 ? `<div style="width:${pctOcupacao}%; background:#198754;" title="${t.horas_trabalhadas}h trabalhadas"></div>` : ''}
            ${pctOcupacao > 0 && pctParada > 0 ? `<div style="width:2px; background:#fff;"></div>` : ''}
            ${pctParada > 0 ? `<div style="width:${pctParada}%; background:#C7860A;" title="${t.horas_paradas}h paradas (líquido)"></div>` : ''}
          </div>
          <div style="font-size:11.5px; color:var(--ink-soft); margin-top:3px;">${t.horas_trabalhadas}h trabalhadas · ${t.horas_paradas}h paradas${t.horas_excedentes ? ` · ${t.horas_excedentes}h excedentes` : ''}${t.dias_pendentes ? ` · ${t.dias_pendentes} dia(s) pendente(s)` : ''}</div>
        </div>`;
      }).join('')}
    </div>`;
}

// Drill-down por indicador (passo 9) — tela própria listando os clientes/equipamentos/O.S. por
// trás do número do card, no mesmo recorte de filtro já aplicado no dashboard (_kpisFiltros).
// Cada indicador tem colunas diferentes porque a unidade de detalhe é diferente: MTTR e Preventiva
// ×Corretiva são por O.S.; MTBF é por intervalo entre 2 O.S. do mesmo equipamento; Disponibilidade
// é por equipamento (não por O.S.).
const KPIS_DETALHE_CONFIG = {
  mtbf: {
    titulo: 'MTBF — detalhe por intervalo',
    colunas: [
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'O.S. anterior', chave: 'os_anterior' },
      { label: 'Data anterior', chave: 'data_anterior', formatar: fmtData },
      { label: 'O.S. atual', chave: 'os_atual' },
      { label: 'Data atual', chave: 'data_atual', formatar: fmtData },
      { label: 'Intervalo', chave: 'intervalo_dias', formatar: (v) => `${v} dias` },
    ],
  },
  mttr: {
    titulo: 'MTTR — detalhe por O.S.',
    colunas: [
      { label: 'O.S.', chave: 'numero_os' },
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'Entrada', chave: 'data_entrada', formatar: fmtData },
      { label: 'Conclusão', chave: 'data_conclusao', formatar: fmtData },
      { label: 'Horas de reparo', chave: 'horas_reparo', formatar: (v) => `${v} h` },
    ],
  },
  disponibilidade: {
    titulo: 'Disponibilidade — detalhe por equipamento',
    colunas: [
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'Contrato', chave: 'tem_contrato_manutencao', formatar: (v) => (v === true ? 'Com contrato' : v === false ? 'Sem contrato' : 'Não informado') },
      { label: 'Horas totais', chave: 'horas_totais', formatar: (v) => `${v} h` },
      { label: 'Horas paradas', chave: 'horas_paradas', formatar: (v) => `${v} h` },
      { label: 'Disponibilidade', chave: 'disponibilidade_percentual', formatar: (v) => (v === null ? '—' : `${v}%`) },
    ],
  },
  backlog: {
    titulo: 'Backlog — O.S. ainda não finalizadas',
    colunas: [
      { label: 'O.S.', chave: 'numero_os' },
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'Tipo', chave: 'tipo' },
      { label: 'Aberta em', chave: 'criado_em', formatar: fmtData },
      { label: 'Horas em aberto', chave: 'horas_aberta', formatar: (v) => `${v} h` },
    ],
  },
  preventiva_corretiva: {
    titulo: 'Preventiva × Corretiva — detalhe por O.S.',
    colunas: [
      { label: 'O.S.', chave: 'numero_os' },
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'Tipo', chave: 'tipo' },
      { label: 'Aberta em', chave: 'criado_em', formatar: fmtData },
    ],
  },
  total_os: {
    titulo: 'O.S. no recorte — detalhe',
    colunas: [
      { label: 'O.S.', chave: 'numero_os' },
      { label: 'Cliente', chave: 'cliente_nome' },
      { label: 'Equipamento', chave: 'equipamento_descricao' },
      { label: 'Tipo', chave: 'tipo' },
      { label: 'Aberta em', chave: 'criado_em', formatar: fmtData },
    ],
  },
};
async function abrirKpiDetalhe(indicador) {
  const config = KPIS_DETALHE_CONFIG[indicador];
  if (!config) return;
  const params = new URLSearchParams({ ..._kpisFiltros, indicador }).toString();
  const { linhas } = await api(`/api/kpis/detalhe?${params}`);
  const main = document.getElementById('main');
  main.innerHTML = `
    <div class="page-head" style="display:flex; justify-content:space-between; align-items:flex-end;">
      <div><h1>${esc(config.titulo)}</h1><p>${linhas.length} registro(s) no recorte de filtro atual.</p></div>
      <button class="btn-outline-sm" onclick="ir('kpis-dashboard')">‹ Home</button>
    </div>
    <div class="panel"><table>
      <tr>${config.colunas.map((c) => `<th>${esc(c.label)}</th>`).join('')}</tr>
      ${linhas.length ? linhas.map((linha) => `
        <tr>${config.colunas.map((c) => `<td data-label="${esc(c.label)}">${esc(c.formatar ? c.formatar(linha[c.chave]) : (linha[c.chave] ?? '—'))}</td>`).join('')}</tr>`).join('')
        : `<tr><td colspan="${config.colunas.length}" class="empty">Nenhum registro nesse recorte.</td></tr>`}
    </table></div>`;
}

// Chart.js (CDN, ver index.html) — se o CDN estiver bloqueado/offline a tela continua útil sem os
// gráficos (cards + tabela de filtros funcionam igual); por isso o guard no topo da função.
function desenharGraficosKpis(meses, kpis) {
  if (typeof Chart === 'undefined') return;
  const labels = meses.map((m) => m.mes);
  // mesma dupla azul/laranja das tags de tipo de O.S. (TIPO_OS_COR: corretiva=blue, preventiva=
  // orange) — pra Preventiva×Corretiva ter sempre o mesmo código de cor em qualquer lugar do app.
  if (_kpisChartTipos) _kpisChartTipos.destroy();
  _kpisChartTipos = new Chart(document.getElementById('kpis-chart-tipos'), {
    type: 'bar',
    data: {
      labels,
      datasets: [
        { label: 'Preventiva', data: meses.map((m) => m.preventivas), backgroundColor: '#E67E22' },
        { label: 'Corretiva', data: meses.map((m) => m.corretivas), backgroundColor: '#1976D2' },
      ],
    },
    options: { responsive: true, scales: { y: { beginAtZero: true, ticks: { precision: 0 } } } },
  });

  if (_kpisChartDonut) _kpisChartDonut.destroy();
  const donutCanvas = document.getElementById('kpis-chart-donut');
  const donutVazio = document.getElementById('kpis-donut-vazio');
  const temDadosDonut = kpis && kpis.percentual_preventiva !== null;
  donutCanvas.style.display = temDadosDonut ? '' : 'none';
  donutVazio.style.display = temDadosDonut ? 'none' : '';
  if (temDadosDonut) {
    _kpisChartDonut = new Chart(donutCanvas, {
      type: 'doughnut',
      data: {
        labels: ['Preventiva', 'Corretiva'],
        datasets: [{
          data: [kpis.percentual_preventiva, kpis.percentual_corretiva],
          backgroundColor: ['#E67E22', '#1976D2'],
          borderColor: '#fff',
          borderWidth: 2,
        }],
      },
      options: {
        responsive: true,
        cutout: '62%',
        plugins: {
          legend: { position: 'bottom', labels: { boxWidth: 10, padding: 12, font: { size: 11 } } },
          tooltip: { callbacks: { label: (ctx) => `${ctx.label}: ${ctx.raw}%` } },
        },
      },
    });
  }
  if (_kpisChartMttr) _kpisChartMttr.destroy();
  const mttrValores = meses.map((m) => m.mttr_horas);
  // pedido do usuário: "No mttr o gráfico colocar valores parcial atualizado durante o mês" — o
  // mês corrente (meses[].parcial, calculado em calcularKpisMensais) entra com reparo em
  // andamento contado parcialmente, pra não ficar sem ponto até o 1º reparo do mês fechar. Esse
  // ponto fica com contorno vazado (em vez de preenchido) e tracejado puxando pra ele, pra não ser
  // lido como um valor fechado igual aos meses anteriores.
  const indiceParcial = meses.findIndex((m) => m.parcial);
  const notaMttr = document.getElementById('kpis-mttr-nota');
  const mostrarNotaParcial = indiceParcial !== -1 && mttrValores[indiceParcial] !== null && mttrValores[indiceParcial] !== undefined;
  if (notaMttr) notaMttr.style.display = mostrarNotaParcial ? '' : 'none';
  // com pouco histórico de corretiva concluída com Laudo Técnico preenchido, a linha vira só 1-2
  // pontos soltos sem nada pra conectar — difícil de ler como "tem dado ali" à primeira vista.
  // Nesse caso (poucos pontos com valor) aumenta o ponto e escreve o valor do lado; com mais
  // meses preenchidos a linha por si só já fica legível, então os rótulos saem do caminho.
  const mttrComDado = mttrValores.filter((v) => v !== null && v !== undefined).length;
  const mostrarRotulosMttr = mttrComDado > 0 && mttrComDado <= 3;
  const rotulosMttrPlugin = {
    id: 'rotulosMttr',
    afterDatasetsDraw(chart) {
      if (!mostrarRotulosMttr) return;
      const { ctx } = chart;
      const pontos = chart.getDatasetMeta(0).data;
      ctx.save();
      ctx.fillStyle = '#1976D2';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      pontos.forEach((ponto, i) => {
        const valor = mttrValores[i];
        if (valor === null || valor === undefined) return;
        ctx.fillText(`${valor} h${i === indiceParcial ? '*' : ''}`, ponto.x, ponto.y - 12);
      });
      ctx.restore();
    },
  };
  _kpisChartMttr = new Chart(document.getElementById('kpis-chart-mttr'), {
    type: 'line',
    data: {
      labels,
      datasets: [{
        label: 'MTTR (h)', data: mttrValores, borderColor: '#1976D2', backgroundColor: 'rgba(25,118,210,.15)',
        fill: true, spanGaps: true, pointHoverRadius: 7,
        pointRadius: mttrValores.map((v, i) => (v === null || v === undefined ? 0 : i === indiceParcial ? 6 : 5)),
        pointBackgroundColor: mttrValores.map((v, i) => (i === indiceParcial ? '#fff' : '#1976D2')),
        pointBorderColor: '#1976D2',
        pointBorderWidth: mttrValores.map((v, i) => (i === indiceParcial ? 2 : 1)),
        segment: { borderDash: (ctx) => (ctx.p1DataIndex === indiceParcial ? [6, 4] : undefined) },
      }],
    },
    options: {
      responsive: true,
      layout: { padding: { top: mostrarRotulosMttr ? 20 : 0 } },
      scales: { y: { beginAtZero: true } },
      plugins: {
        tooltip: {
          callbacks: {
            label: (ctx) => `MTTR: ${ctx.raw} h${ctx.dataIndex === indiceParcial ? ' (parcial — mês em andamento)' : ''}`,
          },
        },
      },
    },
    plugins: [rotulosMttrPlugin],
  });
}

// Exportação Excel (passo 8) — mesmos dados da tela (indicadores + série mensal), no recorte de
// filtro atual, em 2 abas. Reaproveita os <select> de filtro já na tela pra pegar o texto legível
// de cliente/equipamento/técnico escolhido, em vez de só o id. Via SheetJS (CDN, ver index.html),
// mesmo padrão client-side do jsPDF/docx já usados nos outros relatórios — sem rota nova no
// servidor, já que GET /api/kpis e GET /api/kpis/mensal já têm tudo que a planilha precisa.
async function exportarKpisExcel() {
  if (typeof XLSX === 'undefined') return alert('A biblioteca de exportação não carregou (sem conexão com o CDN). Tente novamente mais tarde.');
  const textoSelecionado = (id) => {
    const el = document.getElementById(id);
    return el && el.selectedOptions[0] ? el.selectedOptions[0].textContent : 'Todos';
  };
  const params = new URLSearchParams(_kpisFiltros).toString();
  const sufixo = params ? `?${params}` : '';
  const [{ kpis }, { meses }] = await Promise.all([api(`/api/kpis${sufixo}`), api(`/api/kpis/mensal${sufixo}`)]);

  const abaIndicadores = XLSX.utils.aoa_to_sheet([
    ['Filtros aplicados'],
    ['Período — de', _kpisFiltros.periodo_inicio || 'Todos'],
    ['Período — até', _kpisFiltros.periodo_fim || 'Todos'],
    ['Cliente', textoSelecionado('kf-cliente')],
    [t('equipamento', 'Equipamento'), textoSelecionado('kf-equipamento')],
    ['Técnico', textoSelecionado('kf-tecnico')],
    ['Contrato de manutenção', textoSelecionado('kf-contrato')],
    [],
    ['Indicador', 'Valor', 'Observação'],
    ['MTBF (dias)', kpis.mtbf_dias ?? '—', 'Tempo médio de calendário entre corretivas do mesmo equipamento'],
    ['MTTR (horas)', kpis.mttr_horas ?? '—', 'Tempo médio de reparo (entrada → conclusão do Laudo Técnico)'],
    ['Disponibilidade (%)', kpis.disponibilidade_percentual ?? '—', 'Aproximação por tempo de calendário — sem horas reais de operação ainda'],
    ['Backlog (qtd. de O.S.)', kpis.backlog_qtd, 'O.S. ainda não finalizadas'],
    ['Backlog (horas acumuladas)', kpis.backlog_horas, ''],
    ['% Preventiva', kpis.percentual_preventiva ?? '—', ''],
    ['% Corretiva', kpis.percentual_corretiva ?? '—', ''],
    ['Aderência ao plano', '—', 'Indisponível: depende dos Planos de Manutenção (Fase 2, ainda não implementada)'],
  ]);
  const abaMensal = XLSX.utils.aoa_to_sheet([
    ['Mês', 'Preventivas', 'Corretivas', 'MTTR médio (h)'],
    ...meses.map((m) => [m.mes, m.preventivas, m.corretivas, m.mttr_horas === null || m.mttr_horas === undefined ? '—' : `${m.mttr_horas}${m.parcial ? ' (parcial)' : ''}`]),
  ]);

  const livro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(livro, abaIndicadores, 'Indicadores');
  XLSX.utils.book_append_sheet(livro, abaMensal, 'Mensal');
  const hoje = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(livro, `indicadores-kpis-${hoje}.xlsx`);
}

// ---------- Exportação do dashboard de KPIs em PDF, pronto pra apresentação em reunião ----------
// pedido do usuário: "pode baixar um dashboard visual pra apresentação em reunião" — um PDF com a
// identidade visual do sistema (tiles coloridas, gráficos), não só uma tabela de números como a
// exportação Excel já faz.
function gerarPdfDashboardKpis(kpis, maoDeObra, ranking, logoDataUri, imagens, filtroTexto) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'a4' });
  doc.setProperties({ title: 'Dashboard de Indicadores' });
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  const margem = 36;
  let y = margem;

  function novaPagina() { doc.addPage(); y = margem; }

  function cabecalho(titulo, subtitulo) {
    const xTexto = margem + (logoDataUri ? 34 : 0);
    if (logoDataUri) { try { doc.addImage(logoDataUri.header, 'PNG', margem, y - 6, 26, 30); } catch (e) {} }
    doc.setFontSize(15); doc.setFont(undefined, 'bold'); doc.setTextColor(...PDF_COR.navy);
    doc.text(limparPdf(titulo), xTexto, y + 10);
    doc.setFontSize(9); doc.setFont(undefined, 'normal'); doc.setTextColor(...PDF_COR.inkSoft);
    const linhasSub = doc.splitTextToSize(limparPdf(subtitulo), pageW - margem - xTexto);
    doc.text(linhasSub, xTexto, y + 24);
    y += 24 + linhasSub.length * 11 + 10;
    doc.setDrawColor(...PDF_COR.line); doc.setLineWidth(1);
    doc.line(margem, y, pageW - margem, y);
    y += 18;
  }

  function tileBox(x, ty, w, h, titulo, valor, cor) {
    doc.setFillColor(...cor);
    doc.roundedRect(x, ty, w, h, 8, 8, 'F');
    doc.setFontSize(7.5); doc.setFont(undefined, 'bold'); doc.setTextColor(255, 255, 255);
    doc.text(limparPdf(titulo).toUpperCase(), x + 12, ty + 18);
    doc.setFontSize(16); doc.setFont(undefined, 'bold');
    doc.text(String(valor), x + 12, ty + 38);
  }

  function tituloSecao(txt) {
    if (y > pageH - margem - 60) novaPagina();
    doc.setFillColor(...PDF_COR.blue);
    doc.rect(margem, y - 9, 4, 12, 'F');
    doc.setFontSize(11); doc.setFont(undefined, 'bold'); doc.setTextColor(...PDF_COR.navy);
    doc.text(limparPdf(txt), margem + 10, y); y += 16;
  }

  function tabelaSimples(colunas, larguras, linhas) {
    const larguraTotal = pageW - margem * 2;
    const larg = larguras || colunas.map(() => larguraTotal / colunas.length);
    doc.setFontSize(8.5); doc.setFont(undefined, 'bold'); doc.setTextColor(...PDF_COR.ink);
    let cx = margem;
    colunas.forEach((c, i) => { doc.text(c, cx, y); cx += larg[i]; });
    y += 4;
    doc.setDrawColor(...PDF_COR.line); doc.setLineWidth(0.7); doc.line(margem, y, pageW - margem, y); y += 13;
    doc.setFont(undefined, 'normal'); doc.setTextColor(...PDF_COR.inkSoft);
    linhas.forEach((linha) => {
      if (y > pageH - margem - 16) { novaPagina(); }
      cx = margem;
      linha.forEach((valor, i) => { doc.text(String(valor), cx, y); cx += larg[i]; });
      y += 14;
    });
    y += 12;
  }

  // ===== página 1: tiles + gráficos de distribuição =====
  cabecalho('Dashboard de Indicadores', filtroTexto);

  const gapTile = 10;
  const larguraTile = (pageW - margem * 2 - 2 * gapTile) / 3;
  const alturaTile = 48;
  const tiles = [
    { titulo: 'MTBF', valor: kpis.mtbf_dias !== null ? `${kpis.mtbf_dias} d` : '—', cor: PDF_COR.blue },
    { titulo: 'MTTR', valor: kpis.mttr_horas !== null ? `${kpis.mttr_horas} h` : '—', cor: PDF_COR.purple },
    { titulo: 'Disponibilidade', valor: kpis.disponibilidade_percentual !== null ? `${kpis.disponibilidade_percentual}%` : '—', cor: PDF_COR.green },
    { titulo: 'Backlog', valor: `${kpis.backlog_qtd} O.S.`, cor: PDF_COR.orange },
    { titulo: 'O.S. no recorte', valor: `${kpis.total_os}`, cor: PDF_COR.amber },
    { titulo: 'MOD', valor: maoDeObra.equipe.percentual_ocupacao !== null ? `${maoDeObra.equipe.percentual_ocupacao}%` : '—', cor: PDF_COR.teal },
  ];
  tiles.forEach((tl, i) => {
    const col = i % 3, lin = Math.floor(i / 3);
    tileBox(margem + col * (larguraTile + gapTile), y + lin * (alturaTile + gapTile), larguraTile, alturaTile, tl.titulo, tl.valor, tl.cor);
  });
  y += 2 * (alturaTile + gapTile) + 14;

  const larguraImg = (pageW - margem * 2 - 20) / 2;
  if (imagens.donutTipos || imagens.donutMaoDeObra) {
    tituloSecao('Distribuição');
    doc.setFontSize(9); doc.setFont(undefined, 'bold'); doc.setTextColor(...PDF_COR.ink);
    doc.text('Preventiva × Corretiva', margem, y);
    doc.text('MOD — trabalhadas × paradas', margem + larguraImg + 20, y);
    y += 8;
    if (imagens.donutTipos) { try { doc.addImage(imagens.donutTipos, 'PNG', margem, y, larguraImg, larguraImg); } catch (e) {} }
    if (imagens.donutMaoDeObra) { try { doc.addImage(imagens.donutMaoDeObra, 'PNG', margem + larguraImg + 20, y, larguraImg, larguraImg); } catch (e) {} }
    y += larguraImg + 20;
  }

  // ===== página 2: evolução mensal + tabelas pro handout da reunião =====
  novaPagina();
  if (imagens.barMensal) {
    tituloSecao('Preventiva × Corretiva por mês');
    try { doc.addImage(imagens.barMensal, 'PNG', margem, y, pageW - margem * 2, 140); } catch (e) {}
    y += 156;
  }
  if (imagens.lineMttr) {
    tituloSecao('MTTR por mês (horas)');
    try { doc.addImage(imagens.lineMttr, 'PNG', margem, y, pageW - margem * 2, 140); } catch (e) {}
    y += 156;
  }

  if (maoDeObra.tecnicos.length) {
    tituloSecao('MOD por técnico');
    const larg = [pageW - margem * 2 - 360, 85, 85, 90, 90];
    tabelaSimples(['Técnico', 'Trabalhadas', 'Paradas', 'Excedentes', '% Ocupação'], larg,
      maoDeObra.tecnicos.map((tc) => [tc.tecnico_nome, `${tc.horas_trabalhadas} h`, `${tc.horas_paradas} h`, `${tc.horas_excedentes || 0} h`, tc.percentual_ocupacao !== null ? `${tc.percentual_ocupacao}%` : '—']));
  }
  if (ranking.length) {
    tituloSecao('Técnicos — O.S. concluídas no recorte');
    const larg2 = [pageW - margem * 2 - 100, 100];
    tabelaSimples(['Técnico', 'O.S. concluídas'], larg2, ranking.map((r) => [r.tecnico_nome, r.qtd_os_concluidas]));
  }

  doc.setFontSize(7.5); doc.setTextColor(...PDF_COR.inkSoft);
  const totalPaginas = doc.internal.getNumberOfPages();
  for (let p = 1; p <= totalPaginas; p++) {
    doc.setPage(p);
    doc.text(`${empresaNome()} · gerado em ${new Date().toLocaleDateString('pt-BR')} · página ${p}/${totalPaginas}`, pageW / 2, pageH - 14, { align: 'center' });
  }

  return doc.output('bloburl');
}

async function exportarKpisDashboardPdf() {
  if (typeof window.jspdf === 'undefined') return alert('A biblioteca de exportação de PDF não carregou (sem conexão com o CDN). Tente novamente mais tarde.');
  const textoSelecionado = (id) => {
    const el = document.getElementById(id);
    return el && el.selectedOptions[0] ? el.selectedOptions[0].textContent : 'Todos';
  };
  const params = new URLSearchParams(_kpisFiltros).toString();
  const sufixo = params ? `?${params}` : '';
  const [{ kpis }, { ranking }, maoDeObra] = await Promise.all([
    api(`/api/kpis${sufixo}`), api(`/api/kpis/ranking-tecnicos${sufixo}`), api(`/api/kpis/mao-de-obra${sufixo}`),
  ]);
  const logo = await carregarLogoVariantes();

  const filtroTexto = `Período: ${_kpisFiltros.periodo_inicio || 'todos'} a ${_kpisFiltros.periodo_fim || 'hoje'} · Cliente: ${textoSelecionado('kf-cliente')} · ${t('equipamento', 'Equipamento')}: ${textoSelecionado('kf-equipamento')} · Técnico: ${textoSelecionado('kf-tecnico')}`;

  const imagens = {};
  const donutTipos = document.getElementById('kpis-chart-donut');
  if (donutTipos && kpis.percentual_preventiva !== null) { try { imagens.donutTipos = donutTipos.toDataURL('image/png'); } catch (e) {} }
  const barMensal = document.getElementById('kpis-chart-tipos');
  if (barMensal) { try { imagens.barMensal = barMensal.toDataURL('image/png'); } catch (e) {} }
  const lineMttr = document.getElementById('kpis-chart-mttr');
  if (lineMttr) { try { imagens.lineMttr = lineMttr.toDataURL('image/png'); } catch (e) {} }

  // o donut de Mão de Obra só existe na tela de drill-down (ver abrirMaoDeObraDetalhe), não no
  // dashboard principal de onde esse botão é clicado — desenha num canvas fora da tela só pra
  // capturar a imagem, sem precisar o admin navegar até lá antes de exportar.
  if (typeof Chart !== 'undefined' && (maoDeObra.equipe.horas_trabalhadas || maoDeObra.equipe.horas_paradas)) {
    const canvasTemp = document.createElement('canvas');
    canvasTemp.width = 360; canvasTemp.height = 360;
    canvasTemp.style.position = 'fixed'; canvasTemp.style.left = '-9999px'; canvasTemp.style.top = '0';
    document.body.appendChild(canvasTemp);
    const chartTemp = new Chart(canvasTemp, {
      type: 'doughnut',
      data: { labels: ['Trabalhadas', 'Paradas'], datasets: [{ data: [maoDeObra.equipe.horas_trabalhadas, maoDeObra.equipe.horas_paradas], backgroundColor: ['#198754', '#C7860A'], borderColor: '#fff', borderWidth: 2 }] },
      options: { responsive: false, animation: false, cutout: '62%', plugins: { legend: { position: 'bottom', labels: { boxWidth: 10, padding: 12, font: { size: 13 } } } } },
    });
    await new Promise((resolve) => setTimeout(resolve, 60));
    try { imagens.donutMaoDeObra = canvasTemp.toDataURL('image/png'); } catch (e) {}
    chartTemp.destroy();
    canvasTemp.remove();
  }

  const url = gerarPdfDashboardKpis(kpis, maoDeObra, ranking, logo, imagens, filtroTexto);
  window.open(url, '_blank');
}

// ---- Atrelar equipamento (vincula um item do catálogo a um cliente, com nº de série) ----
// lê o select tri-estado "" (ainda não informado) / "1" (com contrato) / "0" (sem contrato) e
// devolve null/true/false — mesmo formato do campo tem_contrato_manutencao no servidor (passo 11).
function valorContratoSelect(id) {
  const v = document.getElementById(id).value;
  return v === '1' ? true : v === '0' ? false : null;
}

async function renderEquipamentosAtrelar() {
  const [{ equipamentos }, { clientes }] = await Promise.all([api('/api/equipamentos'), api('/api/clientes')]);
  window._clientesCache = clientes;
  window._catalogoCache = equipamentos.filter((e) => e.cliente_id === null);
  const atrelados = equipamentos.filter((e) => e.cliente_id !== null);
  window._atreladosCache = atrelados;
  const main = document.getElementById('main');
  main.innerHTML = `
    <div class="page-head" style="display:flex; justify-content:space-between; align-items:flex-end; flex-wrap:wrap; gap:10px;">
      <div><h1>Atrelar equipamento</h1><p>${atrelados.length} atrelado(s) a clientes</p></div>
      ${botaoVoltarEquipamentosMenu()}
    </div>
    <div class="panel"><div class="panel-head">Atrelar a um cliente</div>
      <div class="form-grid">
        <div><label>Cliente*</label><select id="ae-cliente">${clientes.length ? clientes.map((c) => `<option value="${c.id}">${esc(c.nome_empresa)}</option>`).join('') : '<option value="">Nenhum cliente cadastrado</option>'}</select></div>
        <div><label>${t('equipamento', 'Equipamento')} (catálogo)*</label><select id="ae-equipamento">${window._catalogoCache.length ? window._catalogoCache.map((e) => `<option value="${e.id}">${esc(e.tipo)} — ${esc(e.modelo)}</option>`).join('') : '<option value="">Nenhum equipamento no catálogo</option>'}</select></div>
        <div><label>Número de série*</label><input id="ae-numero-serie"></div>
        <div><label>Data de fabricação (MM/AAAA)</label><input id="ae-data-fabricacao" placeholder="MM/AAAA" maxlength="7"></div>
        <div><label>Localização</label><input id="ae-localizacao" placeholder="ex: Cozinha"></div>
        <div><label>Contrato de manutenção preventiva</label>
          <select id="ae-contrato">
            <option value="">Ainda não informado</option>
            <option value="1">Com contrato</option>
            <option value="0">Sem contrato</option>
          </select>
        </div>
      </div>
      <button class="btn btn-primary btn-sm" onclick="salvarAtrelamento()">Atrelar ao cliente</button>
    </div>
    <div id="form-editar-atrelado"></div>
    <div class="panel"><table>
      <tr><th>Cliente</th><th>Tipo</th><th>Modelo</th><th>Nº de série</th><th>Fabricação</th><th>Contrato</th><th></th></tr>
      ${atrelados.length ? atrelados.map((e) => {
        const cliente = clientes.find((c) => c.id === e.cliente_id);
        return `<tr><td data-label="Cliente">${esc(cliente ? cliente.nome_empresa : '—')}</td><td data-label="Tipo">${esc(e.tipo)}</td><td data-label="Modelo">${esc(e.modelo)}</td><td data-label="Nº de série">${esc(e.numero_serie)}</td><td data-label="Fabricação">${esc(e.data_fabricacao || '—')}</td>
        <td data-label="Contrato">${e.tem_contrato_manutencao === true ? '<span class="tag tag-green">Com contrato</span>' : e.tem_contrato_manutencao === false ? '<span class="tag tag-amber">Sem contrato</span>' : '<span class="tag tag-gray">Não informado</span>'}</td>
        <td class="td-acoes">
          <button class="btn btn-ghost btn-sm" onclick="verHistorico(${e.id})">Histórico</button>
          ${USER.papel === 'administrador' ? `
            <button class="btn-outline-sm" onclick="editarAtrelado(${e.id})">Editar</button>
            <button class="btn-outline-sm" onclick="excluirEquipamento(${e.id})" style="color:var(--red); border-color:var(--red);">Excluir</button>
          ` : ''}
        </td></tr>`;
      }).join('') : `<tr><td colspan="7" class="empty">Nenhum equipamento atrelado a um cliente ainda.</td></tr>`}
    </table></div>
    <div id="historico-eq"></div>`;
}

function editarAtrelado(id) {
  const equipamento = (window._atreladosCache || []).find((e) => e.id === id);
  if (!equipamento) return;
  const cliente = (window._clientesCache || []).find((c) => c.id === equipamento.cliente_id);
  document.getElementById('form-editar-atrelado').innerHTML = `
    <div class="panel"><div class="panel-head">Editar equipamento atrelado — ${esc(cliente ? cliente.nome_empresa : '—')}</div>
      <p style="color:var(--ink-soft); font-size:13px; margin-top:-10px;">Tipo, modelo e cliente não podem ser alterados aqui — exclua e atrele novamente se precisar mudá-los.</p>
      <div class="form-grid">
        <div><label>Tipo</label><input value="${esc(equipamento.tipo)}" disabled></div>
        <div><label>Modelo</label><input value="${esc(equipamento.modelo)}" disabled></div>
        <div><label>Número de série*</label><input id="ea-numero-serie" value="${esc(equipamento.numero_serie)}"></div>
        <div><label>Data de fabricação (MM/AAAA)</label><input id="ea-data-fabricacao" placeholder="MM/AAAA" maxlength="7" value="${esc(equipamento.data_fabricacao || '')}"></div>
        <div><label>Localização</label><input id="ea-localizacao" value="${esc(equipamento.localizacao || '')}"></div>
        <div><label>Contrato de manutenção preventiva</label>
          <select id="ea-contrato">
            <option value="" ${equipamento.tem_contrato_manutencao === null ? 'selected' : ''}>Ainda não informado</option>
            <option value="1" ${equipamento.tem_contrato_manutencao === true ? 'selected' : ''}>Com contrato</option>
            <option value="0" ${equipamento.tem_contrato_manutencao === false ? 'selected' : ''}>Sem contrato</option>
          </select>
        </div>
      </div>
      <div style="display:flex; gap:10px;">
        <button class="btn btn-primary btn-sm" onclick="salvarEdicaoAtrelado(${equipamento.id})">Salvar alterações</button>
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('form-editar-atrelado').innerHTML=''">Cancelar</button>
      </div>
    </div>`;
  document.getElementById('form-editar-atrelado').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

async function salvarEdicaoAtrelado(id) {
  const numeroSerie = document.getElementById('ea-numero-serie').value.trim();
  if (!numeroSerie) return alert('Informe o número de série.');
  const body = {
    numero_serie: numeroSerie,
    data_fabricacao: document.getElementById('ea-data-fabricacao').value,
    localizacao: document.getElementById('ea-localizacao').value,
    tem_contrato_manutencao: valorContratoSelect('ea-contrato'),
  };
  try {
    await api(`/api/equipamentos/${id}`, { method: 'PUT', body });
    mostrarToast('Equipamento atualizado.');
    renderEquipamentosAtrelar();
  } catch (e) { alert('Erro ao salvar: ' + e.message); }
}

async function salvarAtrelamento() {
  const equipamentoId = document.getElementById('ae-equipamento').value;
  const clienteId = document.getElementById('ae-cliente').value;
  const numeroSerie = document.getElementById('ae-numero-serie').value.trim();
  if (!clienteId) return alert('Cadastre um cliente primeiro em Clientes.');
  if (!equipamentoId) return alert('Cadastre um equipamento no catálogo primeiro em Cadastrar equipamento.');
  if (!numeroSerie) return alert('Informe o número de série.');
  const body = {
    cliente_id: clienteId, numero_serie: numeroSerie,
    data_fabricacao: document.getElementById('ae-data-fabricacao').value,
    localizacao: document.getElementById('ae-localizacao').value,
    tem_contrato_manutencao: valorContratoSelect('ae-contrato'),
  };
  try {
    await api(`/api/equipamentos/${equipamentoId}/atrelar`, { method: 'POST', body });
    mostrarToast('Equipamento atrelado ao cliente.');
    renderEquipamentosAtrelar();
  } catch (e) { alert('Erro ao atrelar: ' + e.message); }
}

// ---------- VERSÃO RESTAURANTES/REDE MULTIUNIDADE (Fase 1 — Base) ----------
